window.__BUNDLE__={"generatedAt":"2026-11-09T22:45:58.679370+00:00","recentDays":7,"archiveDays":1825,"recentCutoff":"2026-11-02","archiveCutoff":"2021-11-10","addedToday":1,"addedThisRun":1,"fetchStats":{"hf":274,"arxiv":1331,"total":1605},"freshness":{"latestPaperDate":"2026-11-09","latestPublishedDate":"2026-11-09","latestBatchCount":243,"newInLast24h":270,"newInLast48h":270},"historyTotal":31154,"topicCounts":{"Multi-Agent":3246,"Evaluation":17121,"Planning":2261,"Memory":611,"Code Agent":1255,"Interpretability":1038,"Agentic RAG":1600,"Agentic Search":2153,"RL for LLM":1624,"Reasoning":8246,"Hallucination":1331,"Post-Training":3408,"Alignment":4004,"World Model":620,"Tool Use":1490,"Agent Safety":2799,"Computer Use":406,"Reflection":1108,"VLM Training":2460,"LLM Training":4010,"Fine-tuning":4849,"Multimodal Agent":179,"Agent Framework":987,"Error Attribution":193,"Data Engine":625},"count":36,"recentTotal":2186,"archiveCount":0,"archiveTotal":28968,"sources":{"hf":49,"arxiv":2137,"semanticScholar":0},"archiveSources":{"hf":0,"arxiv":0,"semanticScholar":0},"warnings":[],"notes":["archive is split by year under data/archive/ for fast lazy loading; data/history.json keeps the complete database"],"papers":[{"hfUrl":"https://huggingface.co/papers/2611.09894","tags":["LLM Training","Code Agent"],"upvotes":16,"id":"arxiv:2611.09894","arxiv":"https://arxiv.org/abs/2611.09894","topics":["LLM Training","Code Agent"],"date":"2026-11-09","url":"https://arxiv.org/abs/2611.09894","pdf":"https://arxiv.org/pdf/2611.09894.pdf","submittedDate":"2026-11-06","announceDate":"2026-11-09","authors":["Chaoyang Wang","Sicheng Gao","Junan Hu","Kunyang Li","Dongyang Chen","Yiyang Zhou","Huaxiu Yao","Yong Jae Lee","Radu Timofte","Yuzhang Shang"],"source":"hf","title":"Video-Coder: Reinforcing Agentic Coding for Video Generation","abstract":"Recent years have witnessed remarkable progress in video generation in terms of visual quality and temporal consistency. However, generating videos with precise spatial structure, coherent motion dynamics, and controllable scene composition remains challenging. In this paper, we introduce Video-Coder, the first attempt to train a code-driven video generation agent, which autonomously writes and executes code to construct a dynamic 3D scene (Draft Video) that provides structure and motion signals to downstream video generators. To support this paradigm, we design a dedicated data pipeline and curate two high-quality datasets, Video-Coder-SFT-6k and Video-Coder-RL-2k, which contain diverse prompts and ground-truth reference videos. We further develop the Video- Coder Harness, a unified interactive environment integrating code execution, 3D scene rendering, and execution feedback for agent "},{"hfUrl":"https://huggingface.co/papers/2611.09382","tags":["Reasoning","Evaluation"],"upvotes":10,"id":"arxiv:2611.09382","arxiv":"https://arxiv.org/abs/2611.09382","topics":["Reasoning","Evaluation"],"date":"2026-11-09","url":"https://arxiv.org/abs/2611.09382","pdf":"https://arxiv.org/pdf/2611.09382.pdf","submittedDate":"2026-11-06","announceDate":"2026-11-09","authors":["Junru Hu","Cheng Tang","Wei Li","Hongze Zhu","Chun-Mei Feng","Qi Zhang","Yirong Chen","Ming Hu"],"source":"hf","title":"Exploring Weight-Space Programming: Capabilities, Generalization, and Limitations","abstract":"Weight-Space Programming (WSP) enables reasoning agents to directly inspect and modify neural network parameters, offering an alternative to gradient-based model adaptation. However, its capabilities, cross-task generalization, and practical limitations remain insufficiently understood. We systematically investigate WSP through 16 editing trajectories across seven benchmarks and two model scales (Qwen3.5-0.8B and Qwen3.5-9B). Our findings reveal three key insights. First, WSP can achieve substantial performance gains through highly localized interventions. On full held-out evaluations, accuracy improves by up to 29.45, 4.42, 36.72, and 17.11 percentage points on MATH-500, GPQA Diamond, IFEval, and SciBench, respectively. Notably, modifying only 1,023 parameters yields a 29.45-point improvement. Second, WSP exhibits promising but uneven cross-task generalization. A Math-edited checkpoint "},{"hfUrl":"https://huggingface.co/papers/2611.09017","tags":["Code Agent","Evaluation"],"upvotes":9,"id":"arxiv:2611.09017","arxiv":"https://arxiv.org/abs/2611.09017","topics":["Code Agent","Evaluation"],"date":"2026-11-09","url":"https://arxiv.org/abs/2611.09017","pdf":"https://arxiv.org/pdf/2611.09017.pdf","submittedDate":"2026-11-06","announceDate":"2026-11-09","authors":["Xinjie Lin","Qingle Liu","Wenyi Li","John Lam","Xiaoqiu Wang","Deyao Hong","Mingju Gao","Zheng Jiang","Yizhe Chi","Youjie Zheng","Calvin Xiao","Kaisen Yang","Huan-ang Gao"],"source":"hf","title":"Frontier3DBench: Benchmarking Coding Agents for 3D Creation across Objects, Scenes, and Interactive Open Worlds","abstract":"Coding agents combine visual understanding with program execution, offering a new route to automated 3D creation. By translating images and instructions into editable programs, they bring reconstruction, generation, and editing into a shared workflow. Yet existing benchmarks fragment evaluation across task scopes and protocols, leaving their capabilities across construction levels unclear. We propose Frontier3DBench, a unified benchmark of 145 tasks across 9 categories spanning object, scene, and interactive open-world creation, with joint evaluation of appearance, structure, and behavior. Experiments with 11 model-harness configurations reveal strengths that vary by level: GPT-6.1-sol leads the object and scene levels and achieves the highest overall score of 66.02/100, whereas GPT-6-astra leads interactive world construction. However, all configurations score lower on reference reconst"},{"hfUrl":"https://huggingface.co/papers/2611.09113","tags":["Tool Use","Evaluation","Reflection"],"upvotes":5,"id":"arxiv:2611.09113","arxiv":"https://arxiv.org/abs/2611.09113","topics":["Tool Use","Evaluation","Reflection"],"date":"2026-11-09","url":"https://arxiv.org/abs/2611.09113","pdf":"https://arxiv.org/pdf/2611.09113.pdf","submittedDate":"2026-11-06","announceDate":"2026-11-09","authors":["Chuxue Cao","Jingru Zeng","Boqin Yin","Yujin Zhou","Yidan Huang","Sujin Chen","Jinluan Yang","Haoran Li","Yike Guo","Sirui Han"],"source":"hf","title":"Authorization Drift in LLM Agents: Evaluating Boundary Compliance in Multi-Step Tool Use","abstract":"LLM agents can exceed their authorization boundaries while pursuing user goals without an adversary. We formalize this phenomenon as authorization drift across data, tool, scope, and time, and introduce the Authorization Drift Benchmark (ADB): 648 samples across seven domains, each pairing a sufficient compliant path with an attractive unauthorized shortcut. To ensure executable tasks, tempting shortcuts, and feasible compliant paths, Staged Execution-Reflective Synthesis (SERS) grounds benchmark validation in real agent rollouts rather than LLM self-critique. Across 13 LLMs and three frameworks (25,207 trajectories), greater capability accompanies greater drift, with frontier-capable models exhibiting drift rates of 0.43 to 0.61. Yet 86.18% of tasks admit an observed clean-success trajectory, showing that drift is avoidable. Drift is persistent and dominated by early data over-collectio"},{"hfUrl":"https://huggingface.co/papers/2611.09634","tags":["Post-Training","Alignment","Fine-tuning"],"upvotes":7,"id":"arxiv:2611.09634","arxiv":"https://arxiv.org/abs/2611.09634","topics":["Post-Training","Alignment","Fine-tuning"],"date":"2026-11-09","url":"https://arxiv.org/abs/2611.09634","pdf":"https://arxiv.org/pdf/2611.09634.pdf","submittedDate":"2026-11-06","announceDate":"2026-11-09","authors":["Constantinos Karouzos","Nikolaos Aletras"],"source":"arxiv","title":"Steerable Multi-Objective Group-Relative Preference Optimization with Jointly Trained Low-Rank Adapters","abstract":"Language model deployment often requires different trade-offs between competing objectives as user preferences change, yet standard post-training methods typically produce a single policy for a fixed objective weighting. We introduce LambdaMix, a new parameter efficient method for learning a preference conditioned family of policies with group-relative online reinforcement learning. LambdaMix jointly trains one low-rank adapter per objective over a frozen base model. One preference vector selects the adapter mixture that generates responses and weights the separately normalized rewards used to update the adapters. A single training run supports changing preferences at inference without further optimization. We experiment with four models on helpfulness and harmlessness and on solving math problems while following instructions. We also evaluate the two largest models on rewriting comments"},{"hfUrl":"https://huggingface.co/papers/2611.09891","tags":["Reasoning"],"upvotes":6,"id":"arxiv:2611.09891","arxiv":"https://arxiv.org/abs/2611.09891","topics":["Reasoning"],"date":"2026-11-09","url":"https://arxiv.org/abs/2611.09891","pdf":"https://arxiv.org/pdf/2611.09891.pdf","submittedDate":"2026-11-06","announceDate":"2026-11-09","authors":["Peter Belcak","Greg Heinrich","Saurav Muralidharan","Shizhe Diao","Pavlo Molchanov"],"source":"arxiv","title":"CPU-ARC: Agentic Reasoning Caching for on-CPU Reasoning Reuse","abstract":"Large language models reinvent the wheel all the time. They conflate task-solving with the execution of the solutions, which forces them to solve every problem from scratch. We show that once a task has been reasoned through, the application of its solution to a new problem instance can be done very efficiently and with little involvement from language models. We introduce agentic reasoning caching, a method for constructing robust CPU-executable agentic reasoning caches (ARCs) from LLM reasoning traces. ARCs show on-par performance with frontier LLMs across a range of difficult mathematical and scientific tasks, are fully explainable, continually trainable, robust to input perturbations, and 16-291x cheaper to invoke than the source model."},{"tags":["Post-Training","LLM Training","Reasoning","Evaluation","Fine-tuning"],"upvotes":0,"id":"arxiv:2611.09047","arxiv":"https://arxiv.org/abs/2611.09047","topics":["Post-Training","LLM Training","Reasoning","Evaluation","Fine-tuning","RL for LLM"],"date":"2026-11-09","url":"https://arxiv.org/abs/2611.09047","pdf":"https://arxiv.org/pdf/2611.09047.pdf","submittedDate":"2026-11-06","announceDate":"2026-11-09","authors":["Xiaoyong Yu","Xinge Yu"],"source":"arxiv","title":"Grounding-Aware Judge Reward Reinforcement Learning for Out-of-Domain Face Anti-Spoofing","abstract":"Face Anti-Spoofing (FAS) must distinguish genuine faces from presentation attacks. A unified Multimodal Large Language Model (MLLM) is an attractive solution: it detects physical attacks (print, replay, mask) in one model and produces interpretable forensic evidence via Chain-of-Thought (CoT). A central obstacle to post-training such a model with reinforcement learning is that FAS reasoning has no rule-verifiable ground truth: only the binary verdict is checkable, while the reasoning chain cannot be verified by any hand-crafted rule. Optimizing the verdict alone is therefore a sparse, hackable signal. The model can reach the correct answer through a shortcut such as a false-rejection bias, which does not generalize. We address this with a grounding-aware judge reward. A 32B vision-language judge scores each reasoning chain against the image on evidence anchoring, logical coherence, and d"},{"tags":["Agentic RAG","Agentic Search","LLM Training","Reasoning","Evaluation"],"upvotes":0,"id":"arxiv:2611.09791","arxiv":"https://arxiv.org/abs/2611.09791","topics":["Agentic RAG","Agentic Search","LLM Training","Reasoning","Evaluation"],"date":"2026-11-09","url":"https://arxiv.org/abs/2611.09791","pdf":"https://arxiv.org/pdf/2611.09791.pdf","submittedDate":"2026-11-06","announceDate":"2026-11-09","authors":["Gabriel Souza Baggio","Gabriel Machado Lunardi","Guilherme Medeiros Machado","Subhankar Maity","Faiza Belbachir","José Palazzo Moreira de Oliveira"],"source":"arxiv","title":"Assessing the Impact of Retrieval-Augmented Generation on Algorithmic Problem-Solving","abstract":"Competitive programming problems pose distinctive challenges for Large Language Models, as they demand not only proficient code generation but also advanced algorithmic reasoning. This study presents a Retrieval-Augmented Generation approach specifically designed to enhance the capacity of Large Language Models to address such problems. Our approach integrates an embedding-based retrieval mechanism and a similarity search algorithm to identify analogous problems within a knowledge database, employing a dynamically adjusted threshold to mitigate retrieval noise. We conducted an evaluation using the CodeContests dataset, focusing on the test split problems that exhibit similarity to instances from the training split. The experimental framework considered three conditions: (i) problems provided solely with their original descriptions, (ii) problems supplemented with randomly selected exampl"},{"tags":["Post-Training","LLM Training","Multi-Agent","Reasoning","Alignment"],"upvotes":0,"id":"arxiv:2611.09568","arxiv":"https://arxiv.org/abs/2611.09568","topics":["Post-Training","LLM Training","Multi-Agent","Reasoning","Alignment"],"date":"2026-11-09","url":"https://arxiv.org/abs/2611.09568","pdf":"https://arxiv.org/pdf/2611.09568.pdf","submittedDate":"2026-11-06","announceDate":"2026-11-09","authors":["Nikhil Verma","Dingxian Wang","Mohammad Reza Rezaei","Andrew Rabinovich","Zhao Chen"],"source":"arxiv","title":"Alignment by Confident Debate: Preference Learning from Multi-Agent Debate","abstract":"Post-training language models for reasoning typically rely on gold answers, task-specific verifiers, or learned reward models, limiting scalability when such signals are scarce. Multi-agent debate offers a self-supervised alternative, but converting debate into reliable training supervision remains challenging: majority voting weights agreeing responses equally, lacks a principled tie-breaking rule, and is ill-defined for open-ended tasks without a canonical answer; likelihood-based scoring can conflate fluency with correctness; and homogeneous committees may reinforce correlated errors. We introduce Alignment by Confident Debate (AbCD), which converts debate traces into preference data without gold answer labels. A sampling-diverse committee debates each problem, after which final answers are clustered by task-level semantic equivalence. We use verifiable tasks (mathematical reasoning, "},{"tags":["LLM Training","VLM Training","Reasoning","Evaluation","Fine-tuning"],"upvotes":0,"id":"arxiv:2611.08495","arxiv":"https://arxiv.org/abs/2611.08495","topics":["LLM Training","VLM Training","Reasoning","Evaluation","Fine-tuning"],"date":"2026-11-09","url":"https://arxiv.org/abs/2611.08495","pdf":"https://arxiv.org/pdf/2611.08495.pdf","submittedDate":"2026-08-05","announceDate":"2026-11-09","authors":["Peng Sun","Yi Yang","Mingshuo Chen","Chunxiao Li","Yao Zhu","Huawen Shen","Tianfan Fu"],"source":"arxiv","title":"Rethinking Data Selection as Distribution Matching on Semantic Manifolds","abstract":"Instruction tuning of large language models and large vision language models relies on massive training data, which incurs substantial computational and storage costs. Meanwhile, training data often contains redundancy, noise, and low quality samples. Existing data selection methods mostly rely on diversity, importance, or a combination of both, without explicitly constraining the distributional consistency between the selected subset and the full data in the embedding space. We propose QMAC, a quality aware multiband characteristic function matching method that formulates data selection as a joint optimization problem of distribution matching and quality filtering. QMAC matches the empirical characteristic functions of the selected subset and the full data across multiple frequency scales, capturing both global semantic coverage and local perturbations, while using task related quality "},{"tags":["Agentic RAG","Agentic Search","Reasoning","Evaluation","Multimodal Agent"],"upvotes":0,"id":"arxiv:2611.08935","arxiv":"https://arxiv.org/abs/2611.08935","topics":["Agentic RAG","Agentic Search","Reasoning","Evaluation","Multimodal Agent"],"date":"2026-11-09","url":"https://arxiv.org/abs/2611.08935","pdf":"https://arxiv.org/pdf/2611.08935.pdf","submittedDate":"2026-11-06","announceDate":"2026-11-09","authors":["Jing Hao","Weinan Zhou","Zhihong Lu","Yaling Shen","Yiming Xu","Yefeng Liu","Siyuan Yan","Shuaibo Li","Ming Dai","Junjun He","Zuyi Zhu","Jinjie Gu","Lijun Wu","Jian Wang"],"source":"arxiv","title":"SkinMind: Equipping Agentic RAG with Human-Inspired Graph Probing for Reliable Dermatology AI","abstract":"Reliable dermatology AI requires access to verifiable evidence distributed across heterogeneous textual and visual sources. However, conventional retrieval-augmented generation (RAG) typically relies on one-shot retrieval from flat corpora, limiting its ability to adapt retrieval granularity, explore multi-hop relations, and integrate multimodal clinical evidence. We introduce SkinMind, a multimodal agentic RAG framework that equips policy models with human-inspired graph probing for autonomous evidence seeking. SkinMind organizes retrieval as an iterative interaction between an orchestrator and a graph environment. Through eight hierarchical graph-probing tools, the orchestrator progressively identifies relevant entities, inspects node-level information, traverses relations and paths, and retrieves source-text and visual evidence. This progressive-disclosure design allows the model to a"},{"tags":["Agentic RAG","Agentic Search","Multi-Agent","Reasoning"],"upvotes":0,"id":"arxiv:2611.09298","arxiv":"https://arxiv.org/abs/2611.09298","topics":["Agentic RAG","Agentic Search","Multi-Agent","Reasoning"],"date":"2026-11-09","url":"https://arxiv.org/abs/2611.09298","pdf":"https://arxiv.org/pdf/2611.09298.pdf","submittedDate":"2026-11-06","announceDate":"2026-11-09","authors":["Oliver Noll","Nicholas Tan Jerome","Alexander Lehnen","Frank Simon","Frank Maas"],"source":"arxiv","title":"Towards an Autonomous AI Steward for Large-Scale Physics Experiments: Integrating Causal Diagnostics, RAG, and Conformal Prediction","abstract":"Long-term particle physics experiments face critical operational challenges: monitoring non-stationary machine data streams and preserving tacit expert knowledge. We present the \"Helmholtz Co-Pilot,\" a hybrid Multi-Agent System (MAS) acting as an autonomous experiment steward. The system can be triggered interactively by human operators or autonomously by an asynchronous causal diagnostics engine that runs independently of the MAS reasoning core. Continuously monitoring live hardware streams such as data acquisition and slow control, this engine performs dynamic causal discovery to trace cascading alarms back to their root causes and applies adaptive model selection to keep forecasts reliable across shifting machine states; upon detecting an anomaly, it hands a structured diagnostic report to the MAS. The reasoning layer itself relies on a high-throughput C++ core and a Python edge archi"},{"tags":["Agentic RAG","Agentic Search","Hallucination","Interpretability"],"upvotes":0,"id":"arxiv:2611.09232","arxiv":"https://arxiv.org/abs/2611.09232","topics":["Agentic RAG","Agentic Search","Hallucination","Interpretability"],"date":"2026-11-09","url":"https://arxiv.org/abs/2611.09232","pdf":"https://arxiv.org/pdf/2611.09232.pdf","submittedDate":"2026-11-06","announceDate":"2026-11-09","authors":["Lorenzo Mannocci","Francesca Naretto","Lucia Passaro","Anna Monreale"],"source":"arxiv","title":"RAG-Enhanced LLMs for Interactive Explainability in Clinical Decision Support Systems","abstract":"Artificial Intelligence (AI) is increasingly embedded in high-risks decision-making systems across domains such as healthcare, finance, and the judicial system. As reliance on predictive models grows, so does the demand for Explainable AI (XAI) to ensure transparency, trust, and interpretability. However, existing XAI approaches often fail to present explanations in a format accessible to domain experts, limiting their practical utility. Large Language Models (LLMs) have recently emerged as a bridge between complex models and end-users, offering natural language explanations. Yet, their use introduces new risks, including hallucinated outputs and lack of source traceability. To address these challenges, we propose a Clinical Decision Support System (CDSS) that not only combines standard predictive models with XAI techniques but also incorporates a Retrieval-Augmented Generation module as"},{"tags":["Post-Training","Reasoning","Evaluation","RL for LLM"],"upvotes":0,"id":"arxiv:2611.09872","arxiv":"https://arxiv.org/abs/2611.09872","topics":["Post-Training","Reasoning","Evaluation","RL for LLM"],"date":"2026-11-09","url":"https://arxiv.org/abs/2611.09872","pdf":"https://arxiv.org/pdf/2611.09872.pdf","submittedDate":"2026-11-06","announceDate":"2026-11-09","authors":["Haoyu Wang","Ru Wang","Yuanyuan Wang","Jiaxian Guo","Mingming Gong"],"source":"arxiv","title":"On the Reliability of Majority-Vote Pseudo-Labels in Test-Time Reinforcement Learning","abstract":"Test-time reinforcement learning (TTRL) adapts pretrained language models to unlabeled target-domain data using self-generated pseudo-labels, whose reliability remains poorly understood. We analyze majority-vote supervision for TTRL with online Direct Preference Optimization (DPO) and decompose its error into population-majority bias and prompt-dependent finite-rollout variation. Because population-majority bias is generally unidentifiable without external supervision, we focus on mitigating the downstream effects of finite-rollout variation. We propose \\emph{Prompt-Conditional Distributionally Robust DPO (PC-Dr.DPO)}, which conditions within-prompt robust reweighting on observed vote reliability to make updates from sampling-sensitive prompts more conservative. We further introduce a cache-based mechanism to reduce self-supervised forgetting during online adaptation. Across six mathemat"},{"tags":["LLM Training","Evaluation","Alignment","Data Engine"],"upvotes":0,"id":"arxiv:2611.09863","arxiv":"https://arxiv.org/abs/2611.09863","topics":["LLM Training","Evaluation","Alignment","Data Engine"],"date":"2026-11-09","url":"https://arxiv.org/abs/2611.09863","pdf":"https://arxiv.org/pdf/2611.09863.pdf","submittedDate":"2026-11-06","announceDate":"2026-11-09","authors":["Ruizhi Yuan","Zeqiu Yu","Wei Gao","Wei Chen","Xiwei Tang","Lu Tang"],"source":"arxiv","title":"Flow-Guided Target-Space Alignment via Path Consistency","abstract":"Many multimodal alignment problems require mapping a source modality into a fixed space defined by a target modality, where the target space is not merely an intermediate embedding but is used directly for downstream analysis. In this setting, successful alignment should preserve both the global structure of the target distribution and the instance-level correspondence observed in paired source--target training data. Existing objectives typically address only part of this goal: contrastive losses encourage relative similarity, distribution-matching losses improve marginal agreement, and pointwise regression fits each source sample to its paired target without explicitly modeling target-space path geometry. We propose FlowAlign, a flow-guided target-space alignment method that repurposes conditional flow matching as a training-time alignment signal rather than an inference-time transport "},{"tags":["Agent Safety","Multi-Agent","Evaluation","Reflection"],"upvotes":0,"id":"arxiv:2611.08756","arxiv":"https://arxiv.org/abs/2611.08756","topics":["Agent Safety","Multi-Agent","Evaluation","Reflection"],"date":"2026-11-09","url":"https://arxiv.org/abs/2611.08756","pdf":"https://arxiv.org/pdf/2611.08756.pdf","submittedDate":"2026-11-05","announceDate":"2026-11-09","authors":["Liting Huang","Huizhi Liang","Yi Lei","Xingjun Ma","Varun Ojha"],"source":"arxiv","title":"Debate to Deceive: Poisoning LLM's Fact-Checking via Game-Theoretic Multi-Agent Debate","abstract":"Knowledge attacks on Large Language Models, such as manipulating fact-checking judgments, pose significant risks to AI reliability. Existing approaches -- adversarial suffix/template injection and single-agent self-reflection -- lack robustness across diverse defenses and are prone to confirmation bias and costly trial-and-error, respectively. We propose Debate-to-Deceive (D2D), a multi-agent debate framework grounded in human debate structure and rhetorical style, enabling agents to generate adversarial passages that are semantically coherent, rhetorically effective, and resistant to early confirmation bias. D2D formalizes the adversarial process as an evolutionary game in which agents adaptively evolve their rhetorical strategies (Logos, Pathos, Ethos) through competition. To manage the intractably large LLM output space, we decouple agent behavior into a strategic layer, which selects"},{"tags":["Post-Training","VLM Training","Reasoning","Evaluation"],"upvotes":0,"id":"arxiv:2611.09154","arxiv":"https://arxiv.org/abs/2611.09154","topics":["Post-Training","VLM Training","Reasoning","Evaluation"],"date":"2026-11-09","url":"https://arxiv.org/abs/2611.09154","pdf":"https://arxiv.org/pdf/2611.09154.pdf","submittedDate":"2026-11-06","announceDate":"2026-11-09","authors":["Hongbin Lin","Sizhe Zou","Juangui Xu","Xinyue Xu","Zhuoli Ouyang","Stanislav Kolchin","Chengwei Qin","Zhongxiang Dai","Yao Shu"],"source":"arxiv","title":"Learning When to Think: Dual-Reference Offline Optimization for Adaptive VLM Reasoning","abstract":"Reasoning traces improve vision-language models on complex multimodal tasks, but forcing every input to follow a long reasoning process leads to overthinking and unnecessary inference cost. We study adaptive fast/slow thinking for VLMs, where one model answers directly for simple inputs and reasons step by step when needed. Fast answers and slow traces often come from distinct behavior policies, making a single-reference offline objective misweight one mode. We propose DUAL-REFERENCE BOLT (DR-BOLT), which distinguishes the desired fast/slow mixture reference from the sampling distribution and corrects their mismatch in reward-weighted training. Fast/slow partition competition explains routing in the optimal target; an efficient source-wise correction approximates the exact objective when response formats are well separated. Matched Qwen3-VL comparisons use identical candidate banks to is"},{"tags":["Planning","Memory","Evaluation","World Model"],"upvotes":0,"id":"arxiv:2611.09625","arxiv":"https://arxiv.org/abs/2611.09625","topics":["Planning","Memory","Evaluation","World Model"],"date":"2026-11-09","url":"https://arxiv.org/abs/2611.09625","pdf":"https://arxiv.org/pdf/2611.09625.pdf","submittedDate":"2026-11-06","announceDate":"2026-11-09","authors":["Maxime Burchi","Fayaz Ali Dharejo","Radu Timofte"],"source":"arxiv","title":"Encoding Memory in World Models with Test-Time Model-Based Reinforcement Learning","abstract":"Model-based reinforcement learning (MBRL) approaches have demonstrated strong performance across diverse domains in recent years, learning accurate world models from agent trajectories. However, despite this progress, current approaches still struggle to surpass human performance on tasks that require long-term memory and planning. In this work, we address the problem of long-term memory in MBRL by moving beyond the commonly studied paradigm of architecture design. We introduce Test-Time Model-Based Reinforcement Learning (TT-MBRL), using gradient descent at test time to encode the memory of episode observations into world model parameters. This enables the agent to learn a distinct world model for each episode, improving memory capabilities compared to traditional approaches that solely rely on contextual memory. We first establish a proof of concept on a simplified two-dimensional vari"},{"tags":["VLM Training","Reasoning","Memory","Evaluation"],"upvotes":0,"id":"arxiv:2611.08914","arxiv":"https://arxiv.org/abs/2611.08914","topics":["VLM Training","Reasoning","Memory","Evaluation"],"date":"2026-11-09","url":"https://arxiv.org/abs/2611.08914","pdf":"https://arxiv.org/pdf/2611.08914.pdf","submittedDate":"2026-11-06","announceDate":"2026-11-09","authors":["Ramy ElMallah","Marc Bishara","Hyegang Kim","Yuxi Zhang","Chongyu Zhu","Chi-Guhn Lee"],"source":"arxiv","title":"HomeLoop: A Simulation Framework and Benchmark for Robot-IoT Coordination in Everyday Domestic Assistance and Safety","abstract":"Recent progress in embodied robotics is bringing robots closer to deployment in homes, as vision-language models (VLMs) are demonstrating significant advances in reasoning, making VLM-driven robots promising home assistant agents. These agents will often be introduced into homes that already have cameras, Internet of Things (IoT) devices, and residents with wearables. To fulfill their potential, they need to integrate with existing smart infrastructure and reason through ambiguous scenarios: a smoke alarm may come from a pan about to ignite, a pan already on fire, a resident cooking or a faulty sensor, and each calls for a different response. To that end, we introduce HomeLoop, a simulation framework and benchmark built on Isaac Sim that combines robot bodies, networked devices and wearables, simulated residents and visitors, faulty sensors, and hazards that evolve over time. Our benchma"},{"tags":["VLM Training","Evaluation","Interpretability","Fine-tuning"],"upvotes":0,"id":"arxiv:2611.08897","arxiv":"https://arxiv.org/abs/2611.08897","topics":["VLM Training","Evaluation","Interpretability","Fine-tuning"],"date":"2026-11-09","url":"https://arxiv.org/abs/2611.08897","pdf":"https://arxiv.org/pdf/2611.08897.pdf","submittedDate":"2026-11-06","announceDate":"2026-11-09","authors":["Weidan Xiong","Kaijie Qu","Shihao Feng","Shunqi Fan","Rongyu Xiong","Hui Huang"],"source":"arxiv","title":"Segmenting Geometric Textures of 3D Meshes","abstract":"Recognizing geometric texture patterns on 3D models is critical for applications such as heritage protection, model editing, and 3D printing. Existing 3D model segmentation methods predominantly focus on identifying high-level semantic parts, thereby failing to capture middle-level textures. While recent Vision-Language Models can perform image segmentation with appropriate text prompts, they still struggle to recognize 3D geometric textures. In this work, we present a method that segments 3D mesh models based on middle-level geometric textures. We further introduce a new geometric texture segmentation benchmark and fine-tune SAM3 accordingly. The segmented texture regions are then clustered based on DINO feature similarity and lifted from 2D to 3D. Additionally, we develop an interactive tool to enable both 3D model editing based on our segmentation results and model retrieval from the "},{"tags":["LLM Training","Reasoning","Evaluation","Fine-tuning"],"upvotes":0,"id":"arxiv:2611.09006","arxiv":"https://arxiv.org/abs/2611.09006","topics":["LLM Training","Reasoning","Evaluation","Fine-tuning"],"date":"2026-11-09","url":"https://arxiv.org/abs/2611.09006","pdf":"https://arxiv.org/pdf/2611.09006.pdf","submittedDate":"2026-11-06","announceDate":"2026-11-09","authors":["Yiwen Chen","Fuwei Zhang","Zehao Chen","Deqing Wang","Hehan Li","Peizhi Xu","Hanmeng Liu","Shuanglong Li","Xin Pei","Fuzhen Zhuang","Zhao Zhang"],"source":"arxiv","title":"Rethinking Latent Reasoning for Generative Recommendation: Beyond Teacher-Generated CoT and Recurrent Hidden-State Feedback","abstract":"Latent reasoning in generative recommendation faces two practical barriers: constructing teacher-generated chain-of-thought (CoT) supervision is costly, and recurrent hidden-state feedback requires a specialized execution loop. We revisit both the supervision source and the computation interface. A step-level diagnosis measures how recommendation CoT supports next-item prediction and trace coherence. In the analyzed traces, history analysis is the only step with positive mean contributions on both dimensions, while later preference and intent steps have negative mean answer contributions. Guided by this finding, we propose PHiT (Prefilled, History-Informed Thought Tokens), which learns intermediate states from semantic targets extracted directly from observed item histories. PHiT aggregates cached sparse item encodings to construct these targets and supervises the contextual states of di"},{"tags":["Agentic Search","LLM Training","Fine-tuning"],"upvotes":0,"id":"arxiv:2611.09457","arxiv":"https://arxiv.org/abs/2611.09457","topics":["Agentic Search","LLM Training","Fine-tuning"],"date":"2026-11-09","url":"https://arxiv.org/abs/2611.09457","pdf":"https://arxiv.org/pdf/2611.09457.pdf","submittedDate":"2026-11-06","announceDate":"2026-11-09","authors":["Viraj Mishra","Shubham Gupta","Dhruv Gupta","Yuehong Cassandra Tai","Qunhua Li"],"source":"arxiv","title":"Definitions, Label Names, or Demonstrations? Auditing What Governs LLM Annotation","abstract":"Large language models (LLMs) are increasingly used to annotate social-science texts, but high accuracy does not establish that they apply researcher-supplied category definitions: predictions may instead reflect prior associations with category labels or labeled demonstrations. We introduce a counterfactual audit that reassigns definitions among output labels, distinguishing adherence to supplied definitions from preservation of a dataset's original mapping. Across three political-text datasets, models rarely follow reassigned definitions, and standard fine-tuning strengthens the original mapping without reliably increasing definition adherence. We then study retrieval-augmented annotation. Retrieving the nearest training examples generally outperforms retrieving examples separately within each category despite using fewer demonstrations. On the two tasks with substantial gains, direct \\"},{"tags":["Hallucination","Evaluation","Alignment"],"upvotes":0,"id":"arxiv:2611.09147","arxiv":"https://arxiv.org/abs/2611.09147","topics":["Hallucination","Evaluation","Alignment"],"date":"2026-11-09","url":"https://arxiv.org/abs/2611.09147","pdf":"https://arxiv.org/pdf/2611.09147.pdf","submittedDate":"2026-11-06","announceDate":"2026-11-09","authors":["Anthony Rhodes","Gadi Singer"],"source":"arxiv","title":"BMMS: Policy-Conditioned Measurement of Behavioral Compliance in Language Models","abstract":"Behavioral evaluation of language models fixes its dimensions in advance: hallucination, sycophancy, toxicity, over-refusal. An operator in a regulated industry needs a different question answered: does a system do what a particular rulebook requires? We introduce the Behavioral Misalignment Metric Suite (BMMS), which measures policy-conditioned misalignment by taking a policy corpus as an argument and returning a compliance profile over it, for any published policy and any system that answers in natural language. The Compliance Attainment Score (CAS) measures severity-weighted attainment over the obligations that bind the system, and the Compliance Robustness Margin (CRM) the share of that attainment surviving graded adversarial pressure; Behavioral Invariance (BIV) and the Behavioral Disposition Index (BDI) are specified and released with the suite. Dimensions enter only by passing a p"},{"tags":["Multi-Agent","Memory","Agent Framework"],"upvotes":0,"id":"arxiv:2611.08718","arxiv":"https://arxiv.org/abs/2611.08718","topics":["Multi-Agent","Memory","Agent Framework"],"date":"2026-11-09","url":"https://arxiv.org/abs/2611.08718","pdf":"https://arxiv.org/pdf/2611.08718.pdf","submittedDate":"2026-11-05","announceDate":"2026-11-09","authors":["Emilly Pitman de Castro","Vanessa Silva","Gustavo Kanno","Marcus Santos","Bruno Ferraz do Amaral","Marcelo Nogueira","Lucas Francisco Pellicer","Lucas Lanaro","Pedro Augusto Luiz","João Renato Ribeiro Manesco","Giovanni Carbinatti","Isabela de Lima Santos","Lucas Oliveira Jeronymo","Jeison Fappi","Raul Rotilli Aguirre","Fabio André Frantz","Renata De Paris","Fabiana Marucci","Lohan Silva","Vinicius Diniz Reolon","Wandemberg Gibaut"],"source":"arxiv","title":"Memory-Aware Multi-Agent Architecture with LLM-based Orchestration for Conversational Recommendation","abstract":"Conversational recommender systems often treat user sessions in isolation, limiting their ability to capture how user intent evolves over time. While large language models (LLMs) have improved semantic understanding, they are typically used as isolated components, without addressing how memory, retrieval, and decision-making should be integrated at the system level. In this work, we propose a memory-aware multi-agent architecture for conversational recommendation, in which LLMs act as orchestration layers that coordinate intent refinement, query construction, and interaction flow. A key design principle is the integration of long-term memory as a first-class component, influencing both routing decisions and semantic query formation. We evaluate the system through cross-session memory experiments, multi-turn conversational simulations, and supervisor-driven interaction studies on the Amaz"},{"tags":["Reasoning","Alignment","Interpretability"],"upvotes":0,"id":"arxiv:2611.09356","arxiv":"https://arxiv.org/abs/2611.09356","topics":["Reasoning","Alignment","Interpretability"],"date":"2026-11-09","url":"https://arxiv.org/abs/2611.09356","pdf":"https://arxiv.org/pdf/2611.09356.pdf","submittedDate":"2026-11-06","announceDate":"2026-11-09","authors":["Giuseppe Marra","Pierre Genevès","Meghyn Bienvenu","Thomas Schiex","Sylvie Thiébaux","Silviu Maniu"],"source":"arxiv","title":"Challenges, Opportunities, and Misconceptions in Neurosymbolic AI","abstract":"We examine opportunities for neurosymbolic AI alongside increasingly powerful neural models, particularly with regards to efficiency, safety and interpretability. We identify two major challenges: ensuring semantic alignment between neural and symbolic components, and managing the computational cost of symbolic inference and learning. We discuss representative methodological approaches to these challenges and address several common misconceptions concerning differentiability, independence assumptions, and scalability. This paper synthesizes perspectives developed through discussions in the Neurosymbolic Programming and Reasoning (NPR) working group at the 2026 CNRS workshop Neurosymbolic Methods and Their Applications in Data Science, rather than providing an exhaustive survey."},{"tags":["Reasoning","Evaluation","Reflection"],"upvotes":0,"id":"arxiv:2611.08946","arxiv":"https://arxiv.org/abs/2611.08946","topics":["Reasoning","Evaluation","Reflection"],"date":"2026-11-09","url":"https://arxiv.org/abs/2611.08946","pdf":"https://arxiv.org/pdf/2611.08946.pdf","submittedDate":"2026-11-06","announceDate":"2026-11-09","authors":["Jingdong Zhang","Jionghao Wang","Zhengming Yu","Yancheng Cai","Wei Chow","Chris Choy","Zhiyang Dou","Hang Hua","Jiachen Li","Zhixuan Liu","Chen Wang","Songlin Wei","Siyuan Yang","Yu Yuan","Xiaohang Zhan","Yucheng Zhang","Shuhong Zheng","Xin Li","Lingjie Liu","Wojciech Matusik","Zhengzhong Tu","Wenping Wang"],"source":"arxiv","title":"Flex-RSI: Benchmarking Recursive Self-Improvement of Frontier Agents","abstract":"Frontier language models are increasingly deployed as agents, and how well an agent performs depends not only on its model but also on its harness: the prompts, tools, memory, and control loop through which the model acts. When an agent is applied to a new problem, a natural question is whether it can use the feedback of the task to improve the way it works, and not merely its answer. Most existing benchmarks keep the agent's harness fixed and score the solution it produces, or target large-scale model training. We introduce Flex-RSI, a benchmark for the recursive self-improvement of agents on vision and robotics tasks under a fixed budget. In each round, an executor improves the task solution, which is kept only if it scores higher on held-out validation data, and an improver then revises the harness, including the executor and itself. Every run starts from the same general-purpose harn"},{"tags":["Agent Safety","LLM Training","Fine-tuning"],"upvotes":0,"id":"arxiv:2611.08752","arxiv":"https://arxiv.org/abs/2611.08752","topics":["Agent Safety","LLM Training","Fine-tuning"],"date":"2026-11-09","url":"https://arxiv.org/abs/2611.08752","pdf":"https://arxiv.org/pdf/2611.08752.pdf","submittedDate":"2026-11-05","announceDate":"2026-11-09","authors":["Doniyorkhon Obidov","Honggang Yu","Xiaolong Guo","Kaichen Yang"],"source":"arxiv","title":"AttentionSwitch: Jailbreak Defense for LLMs via Joint Learning of Sparse Attention-Head Selection and Scaling","abstract":"Large language models have achieved remarkable performance across a wide range of tasks, yet they remain susceptible to jailbreak attacks that circumvent safety mechanisms and elicit harmful or unintended outputs. Although safety can be improved through model fine-tuning, such approaches can be computationally expensive and may degrade previously acquired capabilities through catastrophic forgetting. Recent jailbreak defenses have therefore explored targeted interventions on specific model components associated with unsafe behavior. However, existing approaches typically decouple two inherently related decisions: where to intervene and how to modify the selected components. Such sequential optimization may be suboptimal because the optimal intervention location can depend on the intervention applied there, and vice versa. In this work, we introduce AttentionSwitch, the first jailbreak de"},{"tags":["Agentic Search","LLM Training","Evaluation"],"upvotes":0,"id":"arxiv:2611.09866","arxiv":"https://arxiv.org/abs/2611.09866","topics":["Agentic Search","LLM Training","Evaluation"],"date":"2026-11-09","url":"https://arxiv.org/abs/2611.09866","pdf":"https://arxiv.org/pdf/2611.09866.pdf","submittedDate":"2026-11-06","announceDate":"2026-11-09","authors":["Rochak Dhakal","Chen Zhao","Soup Cobb","Xin Qian","Xiaofeng Yang","Weihua Zhou"],"source":"arxiv","title":"GRAC: Graph-Based Retrieval-Augmented Captioning for Surgical Scene Description","abstract":"Purpose: Surgical operative reports support procedural documentation, surgical training, performance assessment, and workflow review. However, extracting meaningful information often requires extensive manual review and clinical expertise. Automated surgical scene descriptions could reduce this burden by leveraging recurring surgical activities and prior knowledge. Methods: We propose GRAC (Graph-Based Retrieval-Augmented Captioning), a framework that represents surgical scenes as graphs capturing relationships among instruments, actions, and anatomical structures. Given an input scene graph, GRAC learns to retrieve relevant graph-caption pairs from training data. It compares instrument-tissue interactions between retrieved examples and the input scene, using comparison features to condition retrieved-caption representations during generation. Results: On the EndoVis-18 benchmark, GRAC a"},{"tags":["Multi-Agent","Evaluation","Fine-tuning"],"upvotes":0,"id":"arxiv:2611.08613","arxiv":"https://arxiv.org/abs/2611.08613","topics":["Multi-Agent","Evaluation","Fine-tuning"],"date":"2026-11-09","url":"https://arxiv.org/abs/2611.08613","pdf":"https://arxiv.org/pdf/2611.08613.pdf","submittedDate":"2026-11-05","announceDate":"2026-11-09","authors":["Binze Li","Zihuan Zhang","Seokhyun Baek","Gillian K. Hadfield","Tianmin Shu"],"source":"arxiv","title":"NormGym: Evaluating Normative Competence through Social Interaction","abstract":"Normative competence, the ability to infer socially enforced expectations from interaction and adjust behavior accordingly, is essential for agents operating in unfamiliar human communities. Yet existing evaluations largely test whether agents can recognize or apply norms they may already know, rather than whether they can acquire previously unknown norms from social interaction. We introduce NormGym, an interactive benchmark for normative competence in which a newcomer must infer a hidden, arbitrary norm while pursuing its own task in a multi-agent community. Success requires distinguishing what is possible from what is permitted, inferring the norm from observed behavior and sanctions, and applying it in new situations. NormGym contains diverse norms and distinct environments, allowing systematic evaluation of current agents, including large language model (LLM) agents. We find that no"},{"tags":["Agentic RAG","Agentic Search","Reasoning"],"upvotes":0,"id":"arxiv:2611.09414","arxiv":"https://arxiv.org/abs/2611.09414","topics":["Agentic RAG","Agentic Search","Reasoning"],"date":"2026-11-09","url":"https://arxiv.org/abs/2611.09414","pdf":"https://arxiv.org/pdf/2611.09414.pdf","submittedDate":"2026-11-06","announceDate":"2026-11-09","authors":["Rosario Napoli","Antonio Celesti","Massimo Villari","Maria Fazio"],"source":"arxiv","title":"Typed-Centrality Grounding for Agentic GraphRAG: A Symbolic Approach for Agentic Reasoning","abstract":"Knowledge Graphs (KGs) and Large Language Models (LLMs) represent two approaches for knowledge representation and reasoning over heterogeneous data. Recent research has explored their integration through Graph Retrieval-Augmented Generation (GraphRAG) systems, which use KGs to provide structured context to LLMs. However, existing GraphRAG approaches treat KGs as homogeneous graphs and rely on textual similarity between the input prompt and the context, rather than using it as a source of deterministic knowledge. This work proposes an agent-based GraphRAG system that introduces a symbolic layer to integrate deterministic reasoning alongside text similarities. This approach is based on the definition of typed centralities for KGs, where centrality measures are computed separately for each specific KG's class. This information is used to construct a symbolic representation that is provided "},{"tags":["Tool Use","Reasoning","Evaluation"],"upvotes":0,"id":"arxiv:2611.09036","arxiv":"https://arxiv.org/abs/2611.09036","topics":["Tool Use","Reasoning","Evaluation"],"date":"2026-11-09","url":"https://arxiv.org/abs/2611.09036","pdf":"https://arxiv.org/pdf/2611.09036.pdf","submittedDate":"2026-11-06","announceDate":"2026-11-09","authors":["Mohamed Elmoghany","Kehan Li","Ruoqu Chen","Tarun Chiruvolu","Shutong Zhang","Ryan Wang","Stephen Tian","Yaru Niu","Michelle Guo","Ding Zhao","Weiyu Liu","Mengdi Xu","Li Fei-Fei","Jiajun Wu"],"source":"arxiv","title":"ToolDex: An Ego-Exo Human Demonstration Dataset for Creative Physical Tool Use","abstract":"Creative tool use is a fundamental human capability and an important step toward general-purpose embodied intelligence. It requires agents to reason about object affordances, physical constraints, and manipulation strategies, especially when standard tools are unavailable. However, progress in this area is limited by the lack of real-world datasets that capture human tool-use behavior with sufficient scale, fidelity, and diversity. Existing benchmarks are often simulation-based, focus on simplified interactions, or lack detailed observations and annotations. We introduce ToolDex, a large-scale egocentric-exocentric (ego-exo) human demonstration dataset for creative physical tool use. ToolDex captures scenarios in which humans select, adapt, and repurpose available objects as tools. Using synchronized egocentric cameras and eight exocentric cameras, the dataset provides high-fidelity mult"},{"tags":["Multi-Agent","Reasoning","Evaluation"],"upvotes":0,"id":"arxiv:2611.08971","arxiv":"https://arxiv.org/abs/2611.08971","topics":["Multi-Agent","Reasoning","Evaluation"],"date":"2026-11-09","url":"https://arxiv.org/abs/2611.08971","pdf":"https://arxiv.org/pdf/2611.08971.pdf","submittedDate":"2026-11-06","announceDate":"2026-11-09","authors":["Disha Sheshanarayana","Rajat Subhra Pal","Manjira Sinha","Tirthankar Dasgupta"],"source":"arxiv","title":"Phantom Consensus: Measuring Social Reasoning in Multi-Agent LLM Decision-Making","abstract":"Multi-agent LLM systems increasingly aggregate judgments across model instances, but reasoning about other agents can itself introduce failure. We study a setting in which LLMs shift their public decisions after observing ambiguous social signals while reporting inaccurate estimates of what other agents privately judged, even when the group's recorded private judgments do not support the apparent consensus. We call this failure phantom consensus and study it as a pluralistic-ignorance-style pattern in controlled LLM collectives. To measure this phenomenon, we introduce PHANTOM-Bench, a benchmark that separates isolated private judgments, public decisions after ambiguous social signals, elicited estimates of the group's private judgment, transparency-based recovery, and controls for neutral public text and explicit vote-following. Across nine closed- and open-weight models, ambiguous publ"},{"tags":["VLM Training","Reasoning","Evaluation"],"upvotes":0,"id":"arxiv:2611.08755","arxiv":"https://arxiv.org/abs/2611.08755","topics":["VLM Training","Reasoning","Evaluation"],"date":"2026-11-09","url":"https://arxiv.org/abs/2611.08755","pdf":"https://arxiv.org/pdf/2611.08755.pdf","submittedDate":"2026-11-05","announceDate":"2026-11-09","authors":["Mingjia Huo","Yao Fu","Bo Chang","Yaqing Wang","Dawei Zhu","Dylan Zhang","Xinyang Yi","Lichan Hong","Ed H. Chi","Hao Zhang","Jiaxi Tang"],"source":"arxiv","title":"AtariBench: Evaluating Spatiotemporal Reasoning of Vision-Language Models in Atari Gameplay","abstract":"Vision-Language Models (VLMs) have achieved strong performance on static visual understanding benchmarks, yet their ability to act in dynamic environments remains less well understood. We introduce AtariBench, a controlled benchmark that evaluates VLMs across 20 Atari 2600 games, requiring models to make sequential decisions from high-temporal-resolution gameplay streams. By decoupling fast in-game dynamics from wall-clock inference speed, AtariBench focuses on whether models can perceive rapid visual state changes, reason over spatiotemporal dynamics, and ground actions in the current observation. Our experiments reveal substantial limitations in state-of-the-art VLMs: models often fail to infer object motion and direction, exhibit brittle sequential decision-making, and over-rely on textual interaction history despite newly appended visual feedback. We further introduce a separability "},{"tags":["LLM Training","Reasoning","Evaluation"],"upvotes":0,"id":"arxiv:2611.09042","arxiv":"https://arxiv.org/abs/2611.09042","topics":["LLM Training","Reasoning","Evaluation"],"date":"2026-11-09","url":"https://arxiv.org/abs/2611.09042","pdf":"https://arxiv.org/pdf/2611.09042.pdf","submittedDate":"2026-11-06","announceDate":"2026-11-09","authors":["Yijun Zhu","Jianxin Wang","Chengchao Shen"],"source":"arxiv","title":"Failure Profiling and Reachable Trajectory Selection for Reasoning Distillation","abstract":"Training smaller language models on reasoning solutions generated by a larger teacher model is the prevailing approach for transferring mathematical reasoning capabilities. However, the student tends to overfit the output distribution of the teacher and generalizes poorly when its own behavior at inference time deviates from the training data. Recent methods attempt to bridge this gap by incorporating error data, yet the corrective trajectories still reflect the reasoning patterns of the teacher, which the student cannot reliably reproduce, leaving the distribution mismatch largely unresolved. We propose a method, Failure Profiling and Reachable Trajectory Selection (FPRT), built on the insight that effective training data should be jointly determined by what the student fails on and what it can realistically learn. Our method first profiles the failure behavior of the student on each pr"},{"tags":["Agentic RAG","Agentic Search","Reasoning"],"upvotes":0,"id":"arxiv:2611.09658","arxiv":"https://arxiv.org/abs/2611.09658","topics":["Agentic RAG","Agentic Search","Reasoning"],"date":"2026-11-09","url":"https://arxiv.org/abs/2611.09658","pdf":"https://arxiv.org/pdf/2611.09658.pdf","submittedDate":"2026-11-06","announceDate":"2026-11-09","authors":["Jie Fu","Yuan Hong","Yue Ning","Wendy Hui Wang"],"source":"arxiv","title":"Differentially Private GraphRAG: Protecting Relation Connectivity and Semantics","abstract":"Graph Retrieval-Augmented Generation (GraphRAG) connects information across documents through entity relationships to support relational reasoning. However, black-box access to GraphRAG systems can enable adversaries to reconstruct knowledge graphs and recover both structural connectivity between entities and the semantics of their relationships. Existing defenses lack formal privacy guarantees and provide limited protection against such reconstruction attacks. We propose RelGuard, the first differentially private framework for GraphRAG, which provides formal privacy guarantees by mitigating connectivity leakage and protecting relations and their semantic meaning through relation removal. We formalize relation differential privacy (relation-DP), which bounds the distinguishability of mechanism outputs according to the semantic distance between alternative relations while accounting for r"},{"tags":["Reasoning","Evaluation","Fine-tuning"],"upvotes":0,"id":"arxiv:2611.09511","arxiv":"https://arxiv.org/abs/2611.09511","topics":["Reasoning","Evaluation","Fine-tuning"],"date":"2026-11-09","url":"https://arxiv.org/abs/2611.09511","pdf":"https://arxiv.org/pdf/2611.09511.pdf","submittedDate":"2026-11-06","announceDate":"2026-11-09","authors":["Dian Jiao","Yuqian Yuan","Jiaqi Zhu","Mingjian Gao","Siwen Tan","Yunqi Cao","Jinhui Li","Sijing Li","Zhenxuan Fan","Haoyang Wang","Wenqiao Zhang","Siliang Tang"],"source":"arxiv","title":"V-STORM: A Structure-Aware Grounded Chain of Thought Dataset for Faithful and Fine-Grained Spatio-Temporal Video Reasoning","abstract":"While MLLMs can often identify what happens in a video, they still struggle with fine-grained spatio-temporal reasoning, which requires precise grounding when and where the supporting evidence appears and composing such evidence into a coherent reasoning chain. This challenge is exacerbated by the lack of scalable data construction and evaluation pipelines that provide granular, verifiable supervision linking reasoning steps to explicit spatio-temporal evidence.To address this gap, we present V-STORM, a structure-aware framework that transforms videos into Spatio-Temporal Scene Graphs (STSGs) and derives Grounded Chain of Thought (GCoT) from validated evidence paths, making each reasoning step traceable to structured and verifiable spatio-temporal evidence.Under this framework, we construct a 260K-sample training set and a 3K-sample human-verified benchmark, both featuring GCoT annotatio"}],"archive":[],"latestPath":"data/latest.json"};
